<?php declare(strict_types=1);require __DIR__.'/app/investment-participation.php';$user=require_verified();$active='investment';$pageTitle='My investments';$rows=rows("SELECT c.*,o.title,o.target_term_months,p.economic_share_percent,p.status participation_status FROM investment_capital_contributions c JOIN investment_opportunities o ON o.id=c.opportunity_id LEFT JOIN investment_participations p ON p.contribution_id=c.id WHERE c.investor_user_id=? ORDER BY c.created_at DESC",[$user['id']]);require __DIR__.'/includes/operations-header.php';?>
<link rel="stylesheet" href="assets/css/investment-market.css?v=<?= filemtime(APP_ROOT.'/assets/css/investment-market.css') ?>"><article class="invest-portfolio"><header><p class="investment-kicker">INVESTOR RECORD</p><h1>My investments</h1><p>Only confirmed capital creates an economic participation and counts toward funding progress.</p></header><table><thead><tr><th>Opportunity</th><th>Amount</th><th>Contribution</th><th>Economic participation</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><a href="investment-view?id=<?= e($row['opportunity_id']) ?>"><?= e($row['title']) ?></a></td><td><?= e($row['currency']) ?> <?= number_format((float)$row['amount'],2) ?></td><td><?= e(str_replace('_',' ',$row['status'])) ?></td><td><?= $row['economic_share_percent']===null?'Pending confirmation':number_format((float)$row['economic_share_percent'],6).'% · no legal title' ?></td><td><?= e($row['created_at']) ?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="invest-empty"><h2>No participation records yet</h2><a href="invest">Browse approved opportunities</a></div><?php endif;?></article><?php require __DIR__.'/includes/operations-footer.php';?>
